import {AgentAvatar} from '@app/dashboard/conversations/avatars/agent-avatar';
import {DashboardIcon} from '@app/dashboard/dashboard-icons';
import {useAuth} from '@common/auth/use-auth';
import {ButtonBase, ButtonBaseProps} from '@ui/buttons/button-base';
import {Trans} from '@ui/i18n/trans';
import {InboxIcon} from '@ui/icons/material/Inbox';
import {SvgIconProps} from '@ui/icons/svg-icon';
import clsx from 'clsx';
import {ReactElement} from 'react';
import {Link, useMatch} from 'react-router';

export function MobileBottomNavbar() {
  const {user} = useAuth();
  if (!user) return null;
  return (
    <div className="dashboard-grid-footer flex items-center border-t bg-background">
      <NavbarButton elementType={Link} to="/agent/conversations">
        <InboxIcon size="sm" />
        <Trans message="Inbox" />
      </NavbarButton>
      <NavbarButton elementType={Link} to="/agent/customers">
        <DashboardIcon name="users" />
        <Trans message="Customers" />
      </NavbarButton>
      <NavbarButton elementType={Link} to="/agent/team">
        <DashboardIcon name="team" />
        <Trans message="Team" />
      </NavbarButton>
      <NavbarButton
        elementType={Link}
        to={`/agent/team/members/${user.id}/details`}
        exactMatch={true}
      >
        <AgentAvatar user={user!} size="w-5 h-5" />
        <Trans message="Profile" />
      </NavbarButton>
    </div>
  );
}

interface NavbarButtonProps extends Omit<ButtonBaseProps, 'to'> {
  children: [ReactElement<SvgIconProps>, ReactElement];
  exactMatch?: boolean;
  to: string;
}
function NavbarButton({
  children,
  exactMatch = false,
  ...props
}: NavbarButtonProps) {
  const {user} = useAuth();
  const profilePageMatch = useMatch('/agent/team/members/:id/details');
  const isCurrentUserProfilePage =
    profilePageMatch?.params.id === `${user!.id}`;
  const routeMatch = useMatch(`${props.to}/*`);
  const isActive = isCurrentUserProfilePage
    ? profilePageMatch.pathname === props.to
    : !!routeMatch;

  return (
    <ButtonBase
      className={clsx(
        'h-16 flex-1 items-center gap-1.5 p-2.5',
        isActive && 'bg-sidebar-accent font-medium text-accent-foreground',
      )}
      display="flex flex-col"
      {...props}
    >
      {children[0]}
      <div className="mt-1.5 text-xs">{children[1]}</div>
    </ButtonBase>
  );
}
